      const { req, res } = createMocks<CustomNextApiRequest, CustomNextApiResponse>({
        method: "POST",
        body: {
          title: "Tennis class",
          slug: "tennis-class-{{$guid}}",
          length: 60,
          hidden: true,
          teamId: 9999,
