  const output = [];
  const length32 = input.length * 32;
  const hexTab = "0123456789abcdef";

  for (let i = 0; i < length32; i += 8) {
    const x = (input[i >> 5] >>> i % 32) & 0xff;
    output.push(parseInt(hexTab[(x >>> 4) & 0x0f] + hexTab[x & 0x0f], 16));
