  let { needImportGeoType, hasChangedIpType } = replaceGeoIpTypes(
    j,
    root,
    geoTypeIdentifier
  )

  let { needImportNextResponse } = replaceNextResponseTypes(j, root)

  let needChanges =
    needImportGeolocation ||
    needImportIpAddress ||
    needImportGeoType ||
    hasChangedIpType ||
    needImportNextResponse

  if (!needChanges) {
    return fileInfo.source
